//
// GLM-5.3 hyper-connections, checked against the reference rather than against my reading of it.
//
// The Swift implementation reuses `DeepseekV4HyperConnection` on the claim that DeepSeek V4's mHC
// and GLM-5.3's mHC are the same mechanism with the same three parameters. That claim is load
// bearing for every token this model produces, and "the shapes line up and the names match" is not
// evidence for it — two different mixing rules can share a parameter shape.
//
// So: `scripts/glm5-hc-oracle.py` transcribes the reference (`Glm5NextTextHyperConnection`,
// `Glm5NextTextHyperHead`, and the bracketing in `Glm5NextTextDecoderLayer.forward` from
// huggingface/transformers `models/glm5_next/modeling_glm5_next.py`) in dependency-free Python, and
// this suite replays its numbers through the Swift path. The sublayer is the identity, which is
// what isolates the wiring: which tensor is the residual, whether `comb` is transposed, and how the
// output is placed back across streams.
//
// Regenerate the fixture with `python3 scripts/glm5-hc-oracle.py`.

import Foundation
import MLX
import MLXLLM
import MLXLMCommon
import MLXNN
import MLXVLM
import Testing

@Suite("GLM-5.3 hyper-connections vs the reference")
