    /// The tolerance is not a formality — it is what this suite tests with.
    ///
    /// Measured agreement is 6e-8 (collapsed, comb), 1.2e-7 (post) and 2.4e-7 (the bracketed
    /// block): float32 machine epsilon against a float64 oracle, which is the floor. The first
    /// version of this suite allowed a slack 2·10^-4 and passed while the implementation was
    /// using `hc_eps` for the input norm — an error whose signature is 1.25e-5. A tolerance loose
    /// enough to admit the bug you are hunting is not a check. 1e-6 sits four times above the
    /// float32 floor and twelve times below that signature.
    static let tolerance: Float = 1e-6

    /// Largest absolute difference, so a failure reports HOW far off rather than just "not equal".
    static func maxAbsDiff(_ a: MLXArray, _ b: [Float]) -> Float {
        let flat = a.asType(.float32).asArray(Float.self)
        guard flat.count == b.count else { return .infinity }
        return zip(flat, b).map { abs($0 - $1) }.max() ?? 0
    }

    static func flatten(_ x: [[[Float]]]) -> [Float] { x.flatMap { $0.flatMap { $0 } } }
    static func flatten(_ x: [[[[Float]]]]) -> [Float] { x.flatMap { flatten($0) } }

    static func makeConnection(_ f: Fixture) -> DeepseekV4HyperConnection {
        let hc = DeepseekV4HyperConnection(
            hcMult: f.shape.hc, sinkhornIterations: f.eps.iters,
            eps: f.eps.hc, normEps: f.eps.rms, hiddenSize: f.shape.hidden)
        // `update(parameters:)` rather than direct assignment: it is the same path the loader uses,
        // so a rename of the parameter keys would fail here too instead of silently leaving zeros.
        hc.update(parameters: ModuleParameters.unflattened([
            "fn": MLXArray(f.in.fn.flatMap { $0 }, [f.in.fn.count, f.in.fn[0].count]),
            "base": MLXArray(f.in.base),
            "scale": MLXArray(f.in.scale),
        ]))
        return hc
    }

    static func streamsArray(_ f: Fixture) -> MLXArray {
        MLXArray(
            flatten(f.in.streams),
            [f.shape.B, f.shape.L, f.shape.hc, f.shape.hidden])
    }

    /// `collapse` must reproduce the reference's `pre`-weighted stream sum, and the `post` / `comb`
    /// it hands to `expand`.
    ///
    /// `comb` is the one worth staring at: Sinkhorn leaves it doubly stochastic but NOT symmetric,
    /// so an implementation that transposed it here (or failed to transpose it later) would still
    /// produce rows and columns summing to one. Comparing the matrix elementwise is what catches
    /// that; comparing its marginals would not.
    @Test("collapse matches the reference's pre-weighted sum, post and comb")
    func collapseMatchesReference() throws {
        let f = Self.fixture
        try MLXMetalTestLock.withLock {
            let hc = Self.makeConnection(f)
            let (collapsed, post, comb) = hc.collapse(Self.streamsArray(f))
            eval(collapsed, post, comb)

            #expect(collapsed.shape == [f.shape.B, f.shape.L, f.shape.hidden])
            #expect(post.shape == [f.shape.B, f.shape.L, f.shape.hc])
            #expect(comb.shape == [f.shape.B, f.shape.L, f.shape.hc, f.shape.hc])

            let dCollapsed = Self.maxAbsDiff(collapsed, Self.flatten(f.out.collapsed))
            let dPost = Self.maxAbsDiff(post, Self.flatten(f.out.post))
            let dComb = Self.maxAbsDiff(comb, Self.flatten(f.out.comb))
            #expect(dCollapsed < Self.tolerance, "collapsed differs from the reference by \(dCollapsed)")
            #expect(dPost < Self.tolerance, "post differs from the reference by \(dPost)")
            #expect(dComb < Self.tolerance, "comb differs from the reference by \(dComb)")

            // The fixture is only a real test of the transpose if its comb is asymmetric.
            let c = comb.asType(.float32).asArray(Float.self)
            let n = f.shape.hc
            var maxAsym: Float = 0
            for i in 0 ..< n {
                for j in 0 ..< n {
                    maxAsym = max(maxAsym, abs(c[i * n + j] - c[j * n + i]))
                }
            }
            #expect(
                maxAsym > 0.1,
                "fixture's comb is near-symmetric (\(maxAsym)); it cannot distinguish a missing transpose")
        }
    }

    /// The full attention-site bracketing with the sublayer as the identity.
    @Test("expand places the block output back across streams as the reference does")
    func expandMatchesReference() throws {
        let f = Self.fixture
        try MLXMetalTestLock.withLock {
            let hc = Self.makeConnection(f)
            let streams = Self.streamsArray(f)
            let (collapsed, post, comb) = hc.collapse(streams)
            let out = hc.expand(blockOut: collapsed, residual: streams, post: post, comb: comb)
            eval(out)

            #expect(out.shape == [f.shape.B, f.shape.L, f.shape.hc, f.shape.hidden])
            let d = Self.maxAbsDiff(out, Self.flatten(f.out.afterBlock))
            #expect(d < Self.tolerance, "the bracketed block output differs from the reference by \(d)")
        }
    }

    /// The reduce is a MEAN. This is the assertion that would have caught the sum this file shipped
    /// with, and the one that will catch a return to it.
    @Test("the final stream collapse is an unweighted mean, not a sum")
    func reduceIsAMean() throws {
        let f = Self.fixture
        try MLXMetalTestLock.withLock {
            let after = MLXArray(
                Self.flatten(f.out.afterBlock),
                [f.shape.B, f.shape.L, f.shape.hc, f.shape.hidden])
            let reduced = Glm5NextLanguageModel.reduceHyperConnectionStream(after)
            eval(reduced)

            #expect(reduced.shape == [f.shape.B, f.shape.L, f.shape.hidden])
            let expected = Self.flatten(f.out.reducedMean)
            let d = Self.maxAbsDiff(reduced, expected)
            #expect(d < 1e-5, "the reduce differs from the reference mean by \(d)")

            // And state the negative directly: a sum is off by exactly hcMult, and no tolerance
            // this test could plausibly carry would hide it.
            let sumInstead = after.sum(axis: -2)
            let dSum = Self.maxAbsDiff(sumInstead, expected)
            #expect(
                dSum > 0.1,
                "a sum is indistinguishable from the mean here (\(dSum)); the test proves nothing")
        }
    }
}
